import{_ as e,o as t,c as l,ag as r}from"./chunks/framework.D7Pdja0E.js";const c=JSON.parse('{"title":"다이렉트 메시지 (DM)","description":"","frontmatter":{},"headers":[],"relativePath":"02-user-guide/dm.md","filePath":"02-user-guide/dm.md","lastUpdated":1776160579000}'),o={name:"02-user-guide/dm.md"};function i(d,a,n,s,h,m){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="다이렉트-메시지-dm" tabindex="-1">다이렉트 메시지 (DM) <a class="header-anchor" href="#다이렉트-메시지-dm" aria-label="Permalink to &quot;다이렉트 메시지 (DM)&quot;">​</a></h1><p>팀원과 1:1 또는 그룹으로 비공개 대화를 할 수 있습니다.</p><h2 id="dm-목록" tabindex="-1">DM 목록 <a class="header-anchor" href="#dm-목록" aria-label="Permalink to &quot;DM 목록&quot;">​</a></h2><p>사이드바 &gt; <strong>다이렉트 메시지</strong>를 클릭하면 진행 중인 DM 목록이 표시됩니다.</p><ul><li>읽지 않은 메시지가 있는 DM은 <strong>굵은 글씨</strong>로 표시됩니다.</li><li>최근 메시지 순으로 정렬됩니다.</li></ul><h2 id="_1-1-dm" tabindex="-1">1:1 DM <a class="header-anchor" href="#_1-1-dm" aria-label="Permalink to &quot;1:1 DM&quot;">​</a></h2><h3 id="새-dm-시작" tabindex="-1">새 DM 시작 <a class="header-anchor" href="#새-dm-시작" aria-label="Permalink to &quot;새 DM 시작&quot;">​</a></h3><ol><li>DM 목록 화면에서 <strong>&quot;+ 새 메시지&quot;</strong> 버튼을 클릭합니다.</li><li>대화 상대를 검색하여 선택합니다.</li><li>메시지를 입력하고 전송합니다.</li></ol><h3 id="기존-dm-이어서-대화" tabindex="-1">기존 DM 이어서 대화 <a class="header-anchor" href="#기존-dm-이어서-대화" aria-label="Permalink to &quot;기존 DM 이어서 대화&quot;">​</a></h3><p>DM 목록에서 대화를 클릭하면 이전 대화 내용을 확인하고 이어서 메시지를 보낼 수 있습니다.</p><h2 id="그룹-dm" tabindex="-1">그룹 DM <a class="header-anchor" href="#그룹-dm" aria-label="Permalink to &quot;그룹 DM&quot;">​</a></h2><h3 id="그룹-dm-생성" tabindex="-1">그룹 DM 생성 <a class="header-anchor" href="#그룹-dm-생성" aria-label="Permalink to &quot;그룹 DM 생성&quot;">​</a></h3><ol><li><strong>&quot;+ 새 메시지&quot;</strong> 버튼을 클릭합니다.</li><li>참여자를 2명 이상 선택합니다.</li><li>메시지를 입력하고 전송하면 그룹 DM이 생성됩니다.</li></ol><h3 id="그룹-dm-특징" tabindex="-1">그룹 DM 특징 <a class="header-anchor" href="#그룹-dm-특징" aria-label="Permalink to &quot;그룹 DM 특징&quot;">​</a></h3><ul><li>참여자 전원에게 메시지가 전달됩니다.</li><li>참여자 목록은 DM 상세 화면 상단에서 확인할 수 있습니다.</li></ul><h2 id="dm-기능" tabindex="-1">DM 기능 <a class="header-anchor" href="#dm-기능" aria-label="Permalink to &quot;DM 기능&quot;">​</a></h2><p>DM에서도 일반 메시지와 동일한 기능을 사용할 수 있습니다:</p><ul><li><strong>쓰레드</strong>: 특정 메시지에 답글 달기</li><li><strong>리액션</strong>: 이모지 반응</li><li><strong>멘션</strong>: <code>@이름</code>으로 특정 참여자 호출</li><li><strong>메시지 수정/삭제</strong>: 본인 메시지 편집 및 삭제</li></ul>',18)])])}const D=e(o,[["render",i]]);export{c as __pageData,D as default};
